// and displays a heading with PocketLedger, description and amount inputs,
// Add expense button, expenses list, delete controls and a category summary.
// No external UI libraries. CSS is responsive, valid and self-contained.
// server/store.js; code below implements durable storage.
const fs = require('node:fs');
function createStore(filePath) {
  let contents = fs.readFileSync(filePath).toString();
  const store = {
    list: () => JSON.parse(contents),
    create: (body) => {
      const { id, description, amount_cents, category } = body;
      contents = contents + `${id},${description},${amount_cents},${category
      }` + '\n';
      return contents;
    },
    delete: (id) => {
      const body = { id };
      contents = contents.replace(`${id},`, '');
      return contents;
    }
  };
  fs.writeFileSync(filePath, contents);
  return store;
}
